INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Масло в ДВС + масляный фильтр', 'Регулярная замена моторного масла обеспечивает надежную защиту двигателя от износа и продлевает срок его службы. Используем только качественные масла, соответствующие спецификациям производителя.', 1900, 'Замена основных жидкостей', 1, true),
('Охлаждающая жидкость', 'Своевременная замена охлаждающей жидкости предотвращает перегрев двигателя и защищает систему охлаждения от коррозии. Рекомендуется проводить каждые 3-4 года.', 3800, 'Замена основных жидкостей', 2, true),
('АКПП ZF (работа + адаптации)', 'Замена масла в коробке передач ZF с последующей адаптацией обеспечивает плавное переключение передач и продлевает ресурс АКПП. Включает сброс и обновление адаптаций.', 5700, 'Замена основных жидкостей', 3, true),
('Раздаточная коробка (работа + адаптации)', 'Обслуживание раздаточной коробки полноприводных моделей предотвращает преждевременный износ механизмов и обеспечивает корректную работу системы полного привода.', 3800, 'Замена основных жидкостей', 4, true),
('Передний редуктор', 'Замена масла в переднем редукторе необходима для бесшумной работы трансмиссии и защиты зубчатых передач от износа. Особенно актуально для полноприводных моделей.', 3800, 'Замена основных жидкостей', 5, true),
('Задний редуктор', 'Регулярное обслуживание заднего редуктора обеспечивает плавную передачу крутящего момента на задние колеса и предотвращает появление посторонних шумов.', 1900, 'Замена основных жидкостей', 6, true);
INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Микрофильтр рециркуляции', 'Фильтр улавливает мельчайшие частицы сажи из отработанных газов, защищая двигатель. Требует периодической замены для поддержания эффективности системы рециркуляции.', 1200, 'Замена фильтров', 7, true),
('Воздушный', 'Чистый воздушный фильтр обеспечивает оптимальное смесеобразование и полноценную работу двигателя. Замена необходима каждые 15-20 тысяч километров.', 800, 'Замена фильтров', 8, true),
('Салонный', 'Салонный фильтр очищает воздух от пыли, пыльцы и вредных веществ, обеспечивая комфортный микроклимат в салоне. Рекомендуется менять дважды в год.', 1200, 'Замена фильтров', 9, true),
('Топливный', 'Топливный фильтр защищает форсунки и топливную систему от загрязнений. Своевременная замена предотвращает потерю мощности и проблемы с запуском двигателя.', 3800, 'Замена фильтров', 10, true);
INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Запрос протокола ошибок эл. систем', 'Комплексная компьютерная диагностика всех электронных систем автомобиля позволяет выявить скрытые неисправности и предотвратить серьезные поломки на ранней стадии.', 3800, 'Зажигание, привода и топливо', 11, true),
('Свечи накаливания, замена', 'Исправные свечи накаливания обеспечивают легкий запуск дизельного двигателя в холодное время года и стабильную работу на холостом ходу.', 6000, 'Зажигание, привода и топливо', 12, true),
('Ремень привода н/а + натяжитель', 'Замена ремня привода навесного оборудования с натяжителем предотвращает внезапный обрыв и обеспечивает надежную работу генератора, насоса ГУР и компрессора кондиционера.', 5700, 'Зажигание, привода и топливо', 13, true),
('Насос системы охлаждения', 'Помпа обеспечивает циркуляцию охлаждающей жидкости. При износе подшипников или крыльчатки двигатель может перегреваться, поэтому важна своевременная замена.', 8000, 'Зажигание, привода и топливо', 14, true),
('Термостат', 'Термостат регулирует температуру двигателя, обеспечивая быстрый прогрев и оптимальный тепловой режим работы. Неисправный термостат может привести к перегреву.', 6000, 'Зажигание, привода и топливо', 15, true),
('Активация скрытых опций', 'Программное кодирование позволяет активировать дополнительные функции автомобиля, доступные на вашей модели: комфортные указатели поворота, складывание зеркал и другие опции.', 3000, 'Зажигание, привода и топливо', 16, true),
('Впускной коллектор + вихревые заслонки + охладитель ОГ системы EGR чистка', 'Профессиональная чистка впускного тракта устраняет отложения сажи и масла, восстанавливает мощность двигателя и снижает расход топлива. Особенно актуально для дизельных моторов.', 40000, 'Зажигание, привода и топливо', 17, true);
INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Запрос протокола ошибок эл. систем', 'Диагностика электронных систем тормозов выявляет неисправности ABS, DSC и помощников торможения, обеспечивая безопасность движения.', 3800, 'Тормозная система', 18, true),
('Колодки передние', 'Замена передних тормозных колодок восстанавливает эффективность торможения. Используем качественные колодки с оптимальным коэффициентом трения.', 3000, 'Тормозная система', 19, true),
('Колодки задние', 'Задние тормозные колодки требуют замены при остаточной толщине менее 3 мм. Обеспечиваем стабильное торможение и отсутствие посторонних звуков.', 3000, 'Тормозная система', 20, true),
('Тормозные диски (П. ось)', 'Замена передних тормозных дисков необходима при выработке, биении или глубоких царапинах. Устанавливаем диски, соответствующие оригинальным спецификациям.', 4000, 'Тормозная система', 21, true),
('Тормозные диски (З. ось)', 'Обновление задних тормозных дисков обеспечивает равномерное распределение тормозного усилия и исключает биение при торможении.', 4600, 'Тормозная система', 22, true),
('Тормозная жидкость, замена + жидкость', 'Тормозная жидкость со временем впитывает влагу и теряет свойства. Полная замена с прокачкой всей системы восстанавливает информативность педали тормоза.', 5500, 'Тормозная система', 23, true),
('Сброс сервиса по колодкам при замене', 'После замены тормозных колодок сбрасываем сервисный счетчик в электронике автомобиля. Услуга предоставляется бесплатно при замене колодок в нашем сервисе.', 0, 'Тормозная система', 24, true);
INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Ввод в эксплуатацию рулевого управления', 'Программная адаптация рулевого управления после ремонта или замены компонентов обеспечивает корректную работу усилителя и систем безопасности.', 3800, 'Рулевой механизм', 25, true),
('Тяга с наконечником, замена 1 шт.', 'Рулевая тяга передает усилие от рулевой рейки на колеса. Изношенные наконечники вызывают люфт и ухудшают управляемость, требуя немедленной замены.', 3000, 'Рулевой механизм', 26, true),
('Жидкость ГУР', 'Замена жидкости гидроусилителя руля обеспечивает легкое вращение руля и защищает насос от преждевременного износа. Рекомендуется каждые 60 тысяч километров.', 4600, 'Рулевой механизм', 27, true),
('Рулевая рейка, ремонт', 'Профессиональный ремонт рулевой рейки устраняет течи масла, люфты и стуки. Проводим полную разборку, замену изношенных деталей и тщательную сборку с последующей регулировкой.', 55000, 'Рулевой механизм', 28, true),
('Рулевая рейка, с/у', 'Снятие и установка рулевой рейки выполняется при ремонте или замены узла. Работа требует точной установки и последующей регулировки углов установки колес.', 11000, 'Рулевой механизм', 29, true),
('Адаптация рулевого управления', 'Программная калибровка датчиков и исполнительных механизмов рулевого управления обеспечивает точную обратную связь и корректную работу систем активной безопасности.', 3800, 'Рулевой механизм', 30, true),
('Сход-развал', 'Регулировка углов установки колес на современном стенде обеспечивает равномерный износ шин, стабильность на дороге и отсутствие увода автомобиля в сторону.', 5700, 'Рулевой механизм', 31, true);
INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Запрос протокола ошибок эл. систем', 'Диагностика электронных компонентов подвески, включая адаптивные амортизаторы и системы регулировки клиренса, выявляет скрытые неисправности.', 3800, 'Подвеска', 32, true),
('Аммортизатор передний', 'Передние амортизаторы гасят колебания кузова и обеспечивают комфорт при движении. Замена необходима при появлении потеков масла или ухудшении управляемости.', 7600, 'Подвеска', 33, true),
('Аммортизатор задний', 'Исправные задние амортизаторы предотвращают раскачку кузова и улучшают сцепление колес с дорогой. Меняем парами для сохранения баланса подвески.', 3800, 'Подвеска', 34, true),
('Стойка стабилизатора', 'Стойки стабилизатора поперечной устойчивости снижают крены кузова в поворотах. Изношенные втулки вызывают стуки и ухудшают управляемость.', 1200, 'Подвеска', 35, true),
('Ступица в сборе', 'Замена ступицы в сборе с подшипником решает проблему гула и вибрации при движении. Используем качественные узлы с длительным сроком службы.', 7600, 'Подвеска', 36, true),
('Ступичный подшипник', 'Изношенный ступичный подшипник издает характерный гул при движении. Своевременная замена предотвращает заклинивание колеса и потенциально опасную ситуацию.', 9500, 'Подвеска', 37, true),
('Пружина подвески', 'Просевшие или сломанные пружины снижают клиренс и ухудшают управляемость. Замена восстанавливает дорожный просвет и комфорт подвески.', 7600, 'Подвеска', 38, true),
('Рычаг продольный', 'Продольные рычаги обеспечивают правильную геометрию подвески. Изношенные сайлентблоки рычагов вызывают нестабильность при разгоне и торможении.', 3800, 'Подвеска', 39, true),
('Рычаг поперечный', 'Поперечные рычаги воспринимают боковые нагрузки и определяют развал-схождение колес. Замена необходима при деформации или износе сайлентблоков.', 3800, 'Подвеска', 40, true),
('Опора шаровая', 'Шаровая опора соединяет рычаг подвески со ступицей, обеспечивая поворот колеса. Критически важный элемент безопасности, требующий регулярной проверки.', 5700, 'Подвеска', 41, true),
('Сайлентблок - перепрессовка', 'Замена изношенных резинометаллических втулок восстанавливает жесткость подвески и устраняет стуки. Выполняем на специальном прессе без повреждения рычагов.', 5000, 'Подвеска', 42, true),
('Сход-развал', 'Точная регулировка углов установки колес после ремонта подвески обеспечивает стабильность движения и равномерный износ шин.', 5700, 'Подвеска', 43, true);
INSERT INTO services (name_ru, description_ru, price_from, category, sort_order, is_active) VALUES
('Запрос протокола ошибок эл. систем', 'Диагностика климатической системы определяет причину некорректной работы кондиционера: от датчиков давления до неисправности компрессора.', 3800, 'Кондиционер', 44, true),
('Перезаправка (без учета фреона)', 'Заправка системы кондиционирования хладагентом восстанавливает холодопроизводительность. Предварительно проверяем герметичность системы на отсутствие утечек.', 3800, 'Кондиционер', 45, true),
('Антибактериальная обработка', 'Профессиональная дезинфекция системы кондиционирования устраняет неприятные запахи, бактерии и грибок в испарителе, обеспечивая чистый воздух в салоне.', 5000, 'Кондиционер', 46, true),
('Компрессор кондиционера, замена', 'Компрессор сжимает хладагент и обеспечивает циркуляцию в системе. При выходе из строя требуется полная замена с последующей заправкой и проверкой герметичности.', 11400, 'Кондиционер', 47, true),
('Диагностика утечки', 'Поиск утечек фреона с использованием ультрафиолетового красителя и специального оборудования позволяет точно определить место разгерметизации системы.', 5700, 'Кондиционер', 48, true),
('Радиатор ДВС - мойка со снятием (без учёта антифриза)', 'Глубокая очистка радиатора охлаждения со снятием удаляет накопившиеся загрязнения, восстанавливая эффективность теплоотдачи и предотвращая перегрев двигателя.', 24000, 'Кондиционер', 49, true);
